html, body {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
    background: #0f0f0f;
    color: #e0e0e0;
    line-height: 1.6;
}

.app-container {
    min-height: 100vh;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 2rem;
}

.main-content {
    width: 100%;
    max-width: 500px;
}

h1 {
    font-size: 2rem;
    margin-bottom: 2rem;
    color: #ffffff;
    font-weight: 600;
}

.notification-form {
    background: #1a1a1a;
    border: 1px solid #2a2a2a;
    border-radius: 12px;
    padding: 2rem;
    box-shadow: 0 10px 40px rgba(0, 0, 0, 0.5);
}

.form-field {
    margin-bottom: 2rem;
}

.radio-group {
    border: none;
    padding: 0;
    margin: 0;
}

.radio-group-legend {
    display: block;
    font-size: 1.1rem;
    font-weight: 600;
    color: #ffffff;
    margin-bottom: 1.5rem;
    padding: 0;
}

.radio-option {
    margin-bottom: 1rem;
    display: flex;
    align-items: center;
}

.radio-option:last-child {
    margin-bottom: 0;
}

/* Hide native radio input */
.radio-option input[type="radio"] {
    appearance: none;
    -webkit-appearance: none;
    width: 0;
    height: 0;
    opacity: 0;
    margin: 0;
    padding: 0;
    position: absolute;
}

.radio-option label {
    display: flex;
    align-items: center;
    cursor: pointer;
    user-select: none;
    gap: 0.75rem;
    padding: 0.75rem;
    border-radius: 8px;
    transition: background-color 0.2s ease;
}

.radio-option label:hover {
    background-color: rgba(255, 255, 255, 0.05);
}

.radio-option label:focus-within {
    outline: 2px solid #4a9eff;
    outline-offset: 2px;
}

/* Custom radio button styling */
.radio-custom {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 20px;
    height: 20px;
    border: 2px solid #4a4a4a;
    border-radius: 50%;
    background-color: #0f0f0f;
    flex-shrink: 0;
    transition: all 0.2s ease;
}

.radio-option input[type="radio"]:checked + label .radio-custom {
    border-color: #4a9eff;
    background-color: #1a1a1a;
    box-shadow: inset 0 0 0 4px #4a9eff;
}

.radio-option input[type="radio"]:focus + label .radio-custom {
    border-color: #4a9eff;
    box-shadow: 0 0 0 3px rgba(74, 158, 255, 0.2);
}

.radio-option input[type="radio"]:checked:focus + label .radio-custom {
    border-color: #4a9eff;
    box-shadow: inset 0 0 0 4px #4a9eff, 0 0 0 3px rgba(74, 158, 255, 0.2);
}

.option-text {
    font-size: 1rem;
    color: #e0e0e0;
    font-weight: 500;
}

.radio-option input[type="radio"]:checked + label .option-text {
    color: #ffffff;
}

.form-actions {
    display: flex;
    gap: 1rem;
    margin-top: 2rem;
}

.btn {
    padding: 0.75rem 1.5rem;
    border: none;
    border-radius: 8px;
    font-size: 1rem;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.2s ease;
    text-align: center;
}

.btn:focus-visible {
    outline: 2px solid #4a9eff;
    outline-offset: 2px;
}

.btn-primary {
    background-color: #4a9eff;
    color: #ffffff;
    flex: 1;
}

.btn-primary:hover {
    background-color: #3a8ee0;
    box-shadow: 0 4px 12px rgba(74, 158, 255, 0.3);
}

.btn-primary:active {
    background-color: #2a7ec0;
}

.btn-primary:disabled {
    background-color: #2a2a2a;
    color: #666666;
    cursor: not-allowed;
}

/* Success message */
.success-message {
    margin-top: 1.5rem;
    padding: 1rem;
    background-color: rgba(76, 175, 80, 0.15);
    border: 1px solid rgba(76, 175, 80, 0.5);
    border-radius: 8px;
    color: #81c784;
    font-weight: 500;
    text-align: center;
    opacity: 0;
    transform: translateY(-10px);
    transition: all 0.3s ease;
    pointer-events: none;
}

.success-message.show {
    opacity: 1;
    transform: translateY(0);
    pointer-events: auto;
}

/* Responsive design */
@media (max-width: 640px) {
    .app-container {
        padding: 1rem;
    }

    .main-content {
        max-width: 100%;
    }

    h1 {
        font-size: 1.5rem;
        margin-bottom: 1.5rem;
    }

    .notification-form {
        padding: 1.5rem;
    }

    .radio-group-legend {
        font-size: 1rem;
        margin-bottom: 1rem;
    }

    .radio-option label {
        padding: 0.5rem;
        gap: 0.5rem;
    }
}

/* Accessibility: Reduced motion */
@media (prefers-reduced-motion: reduce) {
    * {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
    }
}

/* Accessibility: High contrast / Forced colors */
@media (forced-colors: active) {
    .notification-form {
        border-color: CanvasText;
    }

    .radio-custom {
        border-color: CanvasText;
        background-color: Canvas;
    }

    .radio-option input[type="radio"]:checked + label .radio-custom {
        border-color: CanvasText;
        background-color: Canvas;
    }

    .btn-primary {
        border: 2px solid CanvasText;
    }

    .success-message {
        border-color: CanvasText;
    }
}
