AssistantMessageToolRequest(name='create', tool_call_id='tooluse_71lGEG7ndfczYVi4BYA9TX', arguments={'file_text': '// Notification Preference Form Handler
class NotificationForm {
    constructor() {
        this.form = document.getElementById('notificationForm');
        this.successMessage = document.getElementById('successMessage');
        this.init();
    }

    init() {
        this.form.addEventListener('submit', (e) => this.handleSubmit(e));
        this.loadSavedPreference();
    }

    handleSubmit(event) {
        event.preventDefault();

        const selectedOption = document.querySelector('input[name="notification-preference"]:checked');

        if (!selectedOption) {
            alert('Please select a notification preference');
            return;
        }

        const preference = selectedOption.value;

        // Save to localStorage
        localStorage.setItem('notificationPreference', preference);

        // Show success message
        this.showSuccessMessage();

        // Log the preference (in a real app, this would send to a server)
        console.log('Notification preference saved:', preference);
    }

    showSuccessMessage() {
        this.successMessage.classList.add('show');

        // Hide after 3 seconds
        setTimeout(() => {
            this.successMessage.classList.remove('show');
        }, 3000);
    }

    loadSavedPreference() {
        const saved = localStorage.getItem('notificationPreference');

        if (saved) {
            const radio = document.getElementById(saved);
            if (radio) {
                radio.checked = true;
            }
        }
    }
}

// Initialize on DOM ready
document.addEventListener('DOMContentLoaded', () => {
    new NotificationForm();
});
